mapper.select:
with pslaftcommentsdata as ( select DOCUMENT_ID, case when laft_reasons is not null then LAFT_REASONS || ', ' || LAFT_COMMENTS else null end as COMMENTS, LAFT_REVIEW_BY CREATE_ID, LAFT_REVIEW_DATE CREATE_DATE from NYEHMS_STD_MESSAGE_SENT where
FOLLOW_UP_DOC_ID = #{documentId}
DOCUMENT_ID = #{documentId}
union
select comments.DOCUMENT_ID, comments.COMMENTS, comments.CREATE_ID, comments.CREATE_DATE from PS_MESSAGE_COMMENTS comments, NYEHMS_STD_MESSAGE_SENT se where se.document_id = comments.document_id and
se.FOLLOW_UP_DOC_ID = #{documentId}
se.DOCUMENT_ID = #{documentId}
)
SELECT se.DOCUMENT_ID, se.TRIGGER_MSG_TYPE, (SELECT PS_MSG_TYPE_DESCRIPTION FROM CODED_PS_MSG_TYPE WHERE PS_MSG_TYPE =se.TRIGGER_MSG_TYPE) TRIGGER_MSG_DESC, se.TRIGGER_DOC_ID, se.MESSAGE_ENTERED_DATE MESSAGE_ENTERED_DATE_SENT, se.MESSAGE_RECEIVED_DATE MESSAGE_RECEIVED_DATE_SENT, se.CDESSCASEKEY CDESSCASEKEY_SENT, se.CDESSDISMISSED, se.PROCESS_IND, se.LAFT_REASONS, se.LAFT_COMMENTS, case when REVIEW_UID is not null then trim(usr.FULL_NAME) end REVIEW_UID, TO_CHAR(se.REVIEW_DATE, 'MM/DD/YYYY') REVIEW_DATE, se.REVIEW_COMMENTS, se.CREATE_ID TRIGGER_BY, re.*, up_msg.DISPOSITION PS_DATA_DISPOSITION_CODE, TO_CHAR(up_msg.DISPOSITIONDATE, 'MM/DD/YYYY') DISPOSITION_DATE , up_msg.LASTUPDATEDBYNAME UPDATED_BY, up_msg.LASTUPDATEDATE UPDATED_DATE, dispo.SENT_DISPOSITION_DESC DISPOSITION_DESC, up_msg.FIELDNOTE FIELDNOTES, comments.COMMENTS MESSAGE_COMMENTS, case when comments.CREATE_ID is not null then trim(comments_usr.FULL_NAME) end COMMENTS_CREATE_ID, TO_CHAR(comments.CREATE_DATE, 'MM/DD/YYYY HH:MI:SS AM') COMMENTS_CREATE_DATE
FROM NYEHMS_STD_MESSAGE_RETURN re, NYEHMS_STD_MESSAGE_SENT se, NYEHMS_USERS_VW usr, NYEHMS_USERS_VW comments_usr, sti_ps_data up_msg, CODED_SENT_MESSAGE_DISPOSITION dispo, pslaftcommentsdata comments WHERE se.DOCUMENT_ID = re.DOCUMENT_ID(+) and se.DOCUMENT_ID = up_msg.DOCUMENT_ID(+) and up_msg.DISPOSITION = dispo.SENT_DISPOSITION_CODE (+) and se.REVIEW_UID=usr.worker_Id(+) and comments.CREATE_ID=comments_usr.worker_Id(+) and se.document_id = comments.document_id (+) AND NVL (se.PROCESS_IND, 'XX') NOT IN ('N', 'E')
and se.FOLLOW_UP_DOC_ID = #{documentId}
and se.DOCUMENT_ID = #{documentId}
order by se.DOCUMENT_ID asc, comments.CREATE_DATE asc

